mapper.select:
select m.id, m.provider_message_id, m.channel_account_id, m.conversation_id, m.source_event_id, m.client_request_id, m.direction, m.message_kind, m.subject, m.body_text, m.body_html, m.occurred_at, m.received_at, m.ingest_sequence, m.counts_as_unread, m.current_status, m.current_status_at, m.created_by_user_id, m.metadata_jsonb, m.created_at from messages m join conversations cv on cv.id = m.conversation_id where m.conversation_id = #{conversationId}::uuid and ( cv.assigned_user_id = #{userId} or exists (select 1 from team_members tm where tm.team_id = cv.assigned_team_id and tm.user_id = #{userId}) or exists (select 1 from conversation_access_grants g where g.conversation_id = cv.id and g.user_id = #{userId} and g.revoked_at is null and (g.expires_at is null or g.expires_at > now())) )
and (m.occurred_at < #{beforeCursor} or (m.occurred_at = #{beforeCursor} and m.id < #{beforeId}))
order by m.occurred_at desc, m.id desc limit ${page.size}
